<script lang="ts" setup>
defineOptions({
  name: "QRGenerator",
});
import QRCode from "qrcode";
const input = ref<string>("");
const qrSrc = ref<string>("");
const info = ref<string>("支持二维码生成与网页截图识别");

onMounted(async () => {
  const data = await browser.storage.session.get("qrScanResult");

  if (typeof data.qrScanResult === "string") {
    input.value = data.qrScanResult;
    await browser.storage.session.remove("qrScanResult");
  } else {
    const [tab] = await browser.tabs.query({
      active: true,
      currentWindow: true,
    });
    if (tab?.url) {
      input.value = tab.url;
    }
  }
  generate();
});

const generate = async () => {
  try {
    if (!input.value) return;
    qrSrc.value = await QRCode.toDataURL(input.value, {
      width: 220,
      margin: 0,
      color: { dark: "#000000", light: "#ffffff" },
    });
    onSuccess();
  } catch (e) {
    alert("生成失败");
    console.error(e);
  }
};

const copyInput = () => {
  try {
    if (!input.value) return;
    navigator.clipboard.writeText(input.value);
    onSuccess();
  } catch (e) {
    alert("复制失败");
    console.error(e);
  }
};

const download = async () => {
  try {
    if (!qrSrc.value) return;
    const a = document.createElement("a");
    a.href = qrSrc.value;
    a.download = "qrcode.png";
    a.style.position = "absolute";
    a.style.visibility = "hidden";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    onSuccess();
  } catch (e) {
    alert("下载失败");
    console.error(e);
  }
};

const screenshot = async () => {
  await browser.runtime.sendMessage({
    type: "START_QR_SCAN",
  });
  window.close();
};

const onSuccess = () => {
  info.value = "操作已成功";
  setTimeout(() => {
    info.value = "支持二维码生成与网页截图识别";
  }, 1000);
};
</script>

